#include <bits/stdc++.h>
using namespace std;
void solve()
{
    
    int n;
    cin>>n;
    int total = 3*n;
    std::vector<long long>a(total) ;
    for(int i = 0 ; i < total ; i++){
        cin>>a[i];
    }
    
    sort(a.begin() , a.end() , greater<long long >());
    vector<long long>pre(total + 1 , 0);
    for(int i = 0 ; i < total ; i++){
        pre[i+1] = pre[i] + a[i];
    }
    
    auto evaluate = [&](
        int c1 , int c2)->long long {
            return 2*pre[c1] + pre[c1 + 2*c2] + 3*pre[3*n-2 *c1 - c2];
        };
    long long maxStr = 0;
    for(int c1 = 0 ; c1 <= n ; c1++){
        int low = 0 , high = n-c1;
        while(high - low > 3){
            int m1 = low + (high - low)/3;
            int m2 =  high - (high - low)/3;
            
            if(evaluate(c1 , m1) < evaluate(c1 , m2)){
                low = m1;
            }
            else{
                high = m2;
            }
        }
        for(int c2  = low ; c2 <= high ; c2++){
            maxStr = max(maxStr , evaluate(c1 , c2));
        }
    }
    
    cout<<maxStr<<endl;
    
    
    
}
int main() {
	// your code goes here
	int t;
	cin>>t;
	while(t--){
	    solve();
	}
    
}
